//! Read-only exact Message-ID reconciliation. Absence is never proof that mail was not sent.
use crate::*;
fn call(m:&email::Mailbox,calls:Value,then:&str)->Value{accounts::authenticated(http::post_json(&m.endpoint,&json!({"using":["urn:ietf:params:jmap:core","urn:ietf:params:jmap:mail","urn:ietf:params:jmap:submission"],"methodCalls":calls}),then),&m.credential)}
pub fn find_message(m:&email::Mailbox,message_id:&str,then:&str)->Result<Value,String>{email_content::ident(message_id)?;Ok(call(m,json!([["Email/query",{"accountId":m.account,"filter":{"header":["Message-ID",message_id]},"limit":2},"q"],["Email/get",{"accountId":m.account,"#ids":{"resultOf":"q","name":"Email/query","path":"/ids"},"properties":["id","header:Message-ID:asMessageIds"]},"g"]]),then))}
fn pair<'a>(m:&email::Mailbox,r:&'a Value,query:&str,get:&str)->Result<Value,String>{if r["status"]!=200{return Err("Provider reconciliation unavailable; send remains locked".into())}let raw=http::parse_json(r)?;let rows=raw["methodResponses"].as_array().filter(|r|r.len()==2).ok_or("Invalid reconciliation response")?;let mut out=json!({});for(tag,name)in[("q",query),("g",get)]{let matches:Vec<_>=rows.iter().filter(|r|r[2]==tag).collect();if matches.len()!=1||matches[0][0]!=name||matches[0][1]["accountId"]!=m.account{return Err("Reconciliation account/method changed".into())}out[tag]=matches[0][1].clone();}let ids=out["q"]["ids"].as_array().filter(|a|a.len()<=2).ok_or("Ambiguous reconciliation results")?;let list=out["g"]["list"].as_array().filter(|a|a.len()==ids.len()).ok_or("Incomplete reconciliation result")?;if out["g"]["notFound"].as_array().is_none_or(|a|!a.is_empty()){return Err("Reconciliation record changed".into())}let mut seen=std::collections::BTreeSet::new();for row in list{let id=row["id"].as_str().ok_or("Invalid reconciliation identity")?;if !ids.iter().any(|v|v==id)||!seen.insert(id){return Err("Mismatched reconciliation identity".into())}}Ok(out)}
pub fn message(m:&email::Mailbox,expected:&str,r:&Value)->Result<Option<String>,String>{let pair=pair(m,r,"Email/query","Email/get")?;let rows=pair["g"]["list"].as_array().unwrap();if rows.len()>1{return Err("Multiple possible messages; keep send locked and review provider".into())}if let Some(row)=rows.first(){let ids=row["header:Message-ID:asMessageIds"].as_array().ok_or("Provider omitted Message-ID")?;if ids.len()!=1||ids[0]!=expected{return Err("Message-ID did not match exactly".into())}let id=row["id"].as_str().unwrap();email_content::ident(id)?;Ok(Some(id.into()))}else{Ok(None)}}
pub fn submissions(m:&email::Mailbox,email_id:&str,then:&str)->Result<Value,String>{email_content::ident(email_id)?;Ok(call(m,json!([["EmailSubmission/query",{"accountId":m.account,"filter":{"emailIds":[email_id]},"limit":2},"q"],["EmailSubmission/get",{"accountId":m.account,"#ids":{"resultOf":"q","name":"EmailSubmission/query","path":"/ids"},"properties":["id","emailId","undoStatus"]},"g"]]),then))}
pub fn submitted(m:&email::Mailbox,email_id:&str,r:&Value)->Result<bool,String>{let p=pair(m,r,"EmailSubmission/query","EmailSubmission/get")?;let rows=p["g"]["list"].as_array().unwrap();if rows.len()>1{return Err("Multiple submissions require provider review".into())}if let Some(row)=rows.first(){if row["emailId"]!=email_id{return Err("Submission belongs to another email".into())}match row["undoStatus"].as_str(){Some("pending"|"final")=>Ok(true),Some("canceled")=>Ok(false),_=>Err("Unknown provider submission status".into())}}else{Ok(false)}}
pub fn move_to_sent(m:&email::Mailbox,email_id:&str,sent:&str,then:&str)->Result<Value,String>{email_content::ident(email_id)?;email_content::ident(sent)?;let mut mailboxes=json!({});mailboxes[sent]=json!(true);let mut updates=json!({});updates[email_id]=json!({"mailboxIds":mailboxes,"keywords/$draft":null});Ok(call(m,json!([["Email/set",{"accountId":m.account,"update":updates},"move"]]),then))}
pub fn moved(m:&email::Mailbox,email_id:&str,r:&Value)->bool{if r["status"]!=200{return false}let Ok(raw)=http::parse_json(r)else{return false};let Some(rows)=raw["methodResponses"].as_array().filter(|a|a.len()==1)else{return false};let row=&rows[0];row[0]=="Email/set"&&row[2]=="move"&&row[1]["accountId"]==m.account&&row[1]["updated"].get(email_id).is_some()&&row[1]["notUpdated"].get(email_id).is_none()}
#[cfg(test)]mod tests{use super::*;fn m()->email::Mailbox{email::Mailbox::new("https://mail.example.org/jmap","a","drafts","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa").unwrap()}#[test]fn recovery_requires_exact_message_and_never_treats_absence_as_retry(){let raw=json!({"methodResponses":[["Email/query",{"accountId":"a","ids":["e"]},"q"],["Email/get",{"accountId":"a","notFound":[],"list":[{"id":"e","header:Message-ID:asMessageIds":["attempt@onklav.app"]}]},"g"]]});let r=|v:&Value|json!({"status":200,"text":v.to_string()});assert_eq!(message(&m(),"attempt@onklav.app",&r(&raw)).unwrap(),Some("e".into()));assert!(message(&m(),"wrong@onklav.app",&r(&raw)).is_err());let empty=json!({"methodResponses":[["Email/query",{"accountId":"a","ids":[]},"q"],["Email/get",{"accountId":"a","notFound":[],"list":[]},"g"]]});assert_eq!(message(&m(),"attempt@onklav.app",&r(&empty)).unwrap(),None);assert!(!find_message(&m(),"attempt@onklav.app","done").unwrap()["args"]["body"].as_str().unwrap().contains("EmailSubmission/set"));}}
